using UnityEngine;

public class SmoothYRotationMonoBehaviour : MonoBehaviour
{
    // Скорость вращения в градусах за секунду (30 градусов/сек)
    [Header("Настройки вращения")]
    public float rotationSpeedDegreesPerSecond = 30f;

    void Update()
    {
        // Вращение вокруг оси Y на основе текущей скорости и deltaTime
        transform.Rotate(0f, rotationSpeedDegreesPerSecond * Time.deltaTime, 0f, Space.Self);
    }
}

